def check_competition_density(text: str) -> dict:
    """Check if verdict assesses competition saturation per model."""
    score = 0
    details = []

    q9_patterns = [
        r'Q9[_-]?COMPETITION', r'SATURATED', r'CROWDED', r'NICHE',
        r'competition.*(?:density|saturation|assessment)',
        r'how many.*(?:people|founders|competitors).*doing',
    ]
    hits = sum(1 for p in q9_patterns if re.search(p, text, re.IGNORECASE))
    if hits >= 3:
        score += 5
        details.append(f"{hits} competition signals (strong)")
    elif hits >= 1:
        score += 2
        details.append(f"{hits} competition signals (weak)")

    sub_niche = len(re.findall(r'(?i)sub.?niche|specific.*niche|niche.*within', text))
    if sub_niche >= 2:
        score += 3
        details.append(f"{sub_niche} sub-niche specifications")
    elif sub_niche >= 1:
        score += 1
        details.append("1 sub-niche specification")

    generic_model_names = len(re.findall(
        r'(?i)^#{1,4}\s+(?:Newsletter|Micro.?SaaS|Productized Service|Digital Product|Consulting|Freelanc)',
        text, re.MULTILINE))
    if generic_model_names >= 3:
        score = max(0, score - 3)
        details.append(f"PENALTY: {generic_model_names} generic model names without sub-niche")

    return {"score": min(score, 8), "max": 8,
            "detail": "; ".join(details) if details else "no competition density analysis"}


